async function consolidateLegacyRolesOnStartup() {
  try {
    if (!isSupabaseMode()) return;
    const client = getSupabaseBackendClient();
    if (!client) return;
    const legacyCodes = ["management_data", "it_support"];
    const { data: legacyUsers, error: fetchUsersErr } = await client.from("users").select("id, role").in("role", legacyCodes);
    if (!fetchUsersErr && Array.isArray(legacyUsers) && legacyUsers.length > 0) {
      console.warn(
        `[RBAC Audit] Ditemukan ${legacyUsers.length} akun dengan role lama (management_data/it_support). Jalankan migrasi 017_consolidate_roles_to_super_admin.sql secara terkontrol.`
      );
    }
    const { data: legacyRoles, error: fetchRolesErr } = await client.from("roles").select("code").in("code", legacyCodes);
    if (!fetchRolesErr && Array.isArray(legacyRoles) && legacyRoles.length > 0) {
      console.warn(
        `[RBAC Audit] Ditemukan ${legacyRoles.length} baris role lama pada public.roles (${legacyRoles.map((r) => r.code).join(", ")}).`
      );
    } else {
      console.log("[RBAC Audit] Verified public.roles contains strictly 4 consolidated roles.");
    }
  } catch (err) {
    console.warn("[RBAC Audit] Startup role audit warning:", err?.message || err);
  }
}
async function startServer() {
  const PORT = resolveServerPort();
  const HOST = resolveServerHost();
  const httpServer = http.createServer();
  let viteServer = null;
  let isShuttingDown = false;
  const app = await createExpressApp({
    httpServer,
    deferVite: true,
    onViteInstance: (vite) => {
      if (isShuttingDown) {
        void vite.close().catch(() => {
        });
        return;
      }
      viteServer = vite;
    }
  });
  const handleShutdownSignal = (signal) => {
    if (isShuttingDown) return;
    isShuttingDown = true;
    console.log(`[Server] Received ${signal}, shutting down gracefully...`);
    const forceExitTimer = setTimeout(() => {
      process.exit(0);
    }, 1500);
    if (typeof forceExitTimer.unref === "function") {
      forceExitTimer.unref();
    }
    try {
      if (typeof httpServer.closeAllConnections === "function") {
        httpServer.closeAllConnections();
      }
      httpServer.close(() => {
        Promise.resolve(viteServer ? viteServer.close() : void 0).catch(() => {
        }).finally(() => {
          clearTimeout(forceExitTimer);
          process.exit(0);
        });
      });
    } catch {
      process.exit(0);
    }
  };
  process.once("SIGTERM", () => handleShutdownSignal("SIGTERM"));
  process.once("SIGINT", () => handleShutdownSignal("SIGINT"));
  httpServer.on("request", app);
  httpServer.on("error", (err) => {
    console.error(`[Server] Failed to bind http://${HOST}:${PORT} (${err.code || "UNKNOWN"}):`, err.message);
    process.exit(1);
  });
  httpServer.listen(PORT, HOST, () => {
    console.log(`MoraJaws Dispatch Management Server running on http://${HOST}:${PORT}`);
    checkSupabaseConnection().then(async (res) => {
      console.log(`[Startup Check] Supabase: ${res.status.toUpperCase()} - ${res.message}`);
      if (res.status === "connected") {
        await consolidateLegacyRolesOnStartup();
        startSupabasePostgresRealtimeBridge();
      }
    }).catch(() => {
    });
  });
}
